    char lastdir[PATH_MAX_LEN];
    entry_t entries[MAX_ENTRIES];
    int num_entries;
    int filtered_indices[MAX_ENTRIES];
    int num_filtered;
    int cur_idx;
    int top_idx;
    char filter[128];
    int active;
    int detail_mode;
    int show_hidden;
    char sort_order;
