            }
            break;
        case 'a':
            for (int i = 0; i < ctx->num_filtered; i++) {
                int idx = ctx->filtered_indices[i];
                if (!is_selected(ctx->entries[idx].fullpath)) {
                    toggle_select(ctx->entries[idx].fullpath);
                }
            }
            break;
        case 'd':
            ctx->detail_mode = !ctx->detail_mode;
            break;
        case '.':
            ctx->show_hidden = !ctx->show_hidden;
            read_directory(ctx);
            break;
        case '?':
            show_help();
            break;
        case '\t':
            cur_ctx = (cur_ctx + 1) % NUM_CONTEXTS;
            contexts[cur_ctx].active = 1;
            read_directory(&contexts[cur_ctx]);
            break;
        case '1': case '2': case '3': case '4':
        case '5': case '6': case '7': case '8':
            cur_ctx = ch - '1';
            contexts[cur_ctx].active = 1;
            read_directory(&contexts[cur_ctx]);
            break;
        case '~': {
            const char *home = getenv("HOME");
            if (home) {
                snprintf(ctx->dir, sizeof(ctx->dir), "%s", home);
                ctx->cur_idx = 0;
                read_directory(ctx);
            }
            break;
        }
        case 'g':
        case 1:
            ctx->cur_idx = 0;
            break;
        case 'G':
        case 5:
            if (ctx->num_filtered > 0) ctx->cur_idx = ctx->num_filtered - 1;
            break;
        default:
            break;
        }
    }

    endwin();
    return 0;
}
