static void draw_ui(void) {
    clear();
    context_t *ctx = &contexts[cur_ctx];

    move(0, 0);
    for (int i = 0; i < NUM_CONTEXTS; i++) {
        if (i == cur_ctx) {
            attron(A_BOLD | A_REVERSE);
            printw("%d", i + 1);
            attroff(A_BOLD | A_REVERSE);
            printw(" ");
        } else {
            printw("%d ", i + 1);
        }
    }
    attron(A_UNDERLINE);
    printw("%s", ctx->dir);
    attroff(A_UNDERLINE);

    int max_y, max_x;
    getmaxyx(stdscr, max_y, max_x);
    (void)max_x;

    int list_height = max_y - 2;
    if (ctx->cur_idx < ctx->top_idx) ctx->top_idx = ctx->cur_idx;
    if (ctx->cur_idx >= ctx->top_idx + list_height) ctx->top_idx = ctx->cur_idx - list_height + 1;

    for (int i = 0; i < list_height && (ctx->top_idx + i) < ctx->num_filtered; i++) {
        int idx = ctx->filtered_indices[ctx->top_idx + i];
        entry_t *e = &ctx->entries[idx];
        move(i + 1, 0);

        int is_cur = (ctx->top_idx + i == ctx->cur_idx);
        if (is_cur) attron(A_BOLD | A_REVERSE);

        int sel = is_selected(e->fullpath);

        if (ctx->detail_mode) {
            char time_str[32];
            struct tm *tm_info = localtime(&e->mtime);
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M", tm_info);

            char sz_str[32];
            format_size(e->size, sz_str, sizeof(sz_str));

            int mode_oct = e->mode & 0777;

            printw("%s%s  %3o  %8s  %s%s",
                   is_cur ? ">" : " ",
                   time_str, mode_oct, sz_str, e->name,
                   e->is_dir ? "/" : e->is_exec ? "*" : e->is_link ? "@" : "");
        } else {
            printw("%s%s%s",
                   sel ? "+" : " ",
                   e->name,
                   e->is_dir ? "/" : e->is_exec ? "*" : e->is_link ? "@" : "");
        }

        if (is_cur) attroff(A_BOLD | A_REVERSE);
    }

    move(max_y - 1, 0);
    if (ctx->num_filtered > 0 && ctx->cur_idx < ctx->num_filtered) {
        int idx = ctx->filtered_indices[ctx->cur_idx];
        entry_t *e = &ctx->entries[idx];

        char time_str[32];
        struct tm *tm_info = localtime(&e->mtime);
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M", tm_info);

        char perm_str[12];
        format_perms(e->mode, perm_str);

        char sz_str[32];
        format_size(e->size, sz_str, sizeof(sz_str));

        if (num_selected > 0) {
            printw("%d/%d  +%d  %s %s %s", ctx->cur_idx + 1, ctx->num_filtered, num_selected, time_str, perm_str, sz_str);
        } else {
            printw("%d/%d  %s %s %s", ctx->cur_idx + 1, ctx->num_filtered, time_str, perm_str, sz_str);
        }
    } else {
        printw("0/0");
    }

    refresh();
}

static void save_selection(void) {
    if (!cfg.selection_file) return;

    FILE *f = stdout;
    if (strcmp(cfg.selection_file, "-") != 0) {
        f = fopen(cfg.selection_file, "w");
        if (!f) return;
    }

    char sep = cfg.null_separator ? '\0' : '\n';

    if (num_selected > 0) {
        for (int i = 0; i < num_selected; i++) {
            fputs(selected_paths[i], f);
            fputc(sep, f);
        }
    } else if (contexts[cur_ctx].num_filtered > 0) {
        int idx = contexts[cur_ctx].filtered_indices[contexts[cur_ctx].cur_idx];
        fputs(contexts[cur_ctx].entries[idx].fullpath, f);
        fputc(sep, f);
    }

    if (f != stdout) fclose(f);
}

int main(int argc, char *argv[]) {
    cfg.detail_mode = 0;
    cfg.show_hidden = 0;

    int opt;
    while ((opt = getopt(argc, argv, "aAb:BcCdDeEfF:gHiJKl:nNoOp:P:QrRs:St:T:uUVxz0h")) != -1) {
        switch (opt) {
        case 'V':
            print_version();
            return 0;
        case 'h':
            print_usage();
            return 0;
        case 'd':
            cfg.detail_mode = 1;
            break;
        case 'H':
            cfg.show_hidden = 1;
            break;
        case 'n':
            cfg.type_to_nav = 1;
            break;
        case 'p':
            cfg.selection_file = optarg;
            break;
        case '0':
            cfg.null_separator = 1;
            break;
        case 'K':
            return 0;
        case 'T':
            cfg.sort_order = optarg[0];
            break;
        case '?':
            print_usage();
            return 1;
        default:
            break;
        }
    }

    const char *start_path = ".";
    if (optind < argc) {
        start_path = argv[optind];
    }

    char abs_start[PATH_MAX_LEN];
    if (start_path[0] == '~') {
        const char *home = getenv("HOME");
        snprintf(abs_start, sizeof(abs_start), "%s%s", home ? home : "", start_path + 1);
    } else {
        snprintf(abs_start, sizeof(abs_start), "%s", start_path);
    }

    size_t len = strlen(abs_start);
    if (len > 1 && abs_start[len - 1] == '/') {
        struct stat st;
        if (stat(abs_start, &st) != 0) {
            if (isatty(STDIN_FILENO)) {
                char tmp[PATH_MAX_LEN];
                snprintf(tmp, sizeof(tmp), "mkdir -p \"%s\"", abs_start);
                int r = system(tmp);
                (void)r;
            }
        }
    }

    char resolved_path[PATH_MAX_LEN];
    if (realpath(abs_start, resolved_path) == NULL) {
        if (!isatty(STDIN_FILENO)) {
            fprintf(stderr, "0 entries\n");
            return 1;
        }
        if (realpath(".", resolved_path) == NULL) {
            snprintf(resolved_path, sizeof(resolved_path), ".");
        }
    }

    if (!isatty(STDIN_FILENO)) {
        fprintf(stderr, "0 entries\n");
        return 1;
    }

    for (int i = 0; i < NUM_CONTEXTS; i++) {
        snprintf(contexts[i].dir, sizeof(contexts[i].dir), "%s", resolved_path);
        contexts[i].active = (i == 0);
        contexts[i].detail_mode = cfg.detail_mode;
        contexts[i].show_hidden = cfg.show_hidden;
        contexts[i].sort_order = cfg.sort_order;
    }

    read_directory(&contexts[cur_ctx]);

    setlocale(LC_ALL, "");
    initscr();
    raw();
    noecho();
    keypad(stdscr, TRUE);
    curs_set(0);

    if (has_colors()) {
        start_color();
        use_default_colors();
    }

    int running = 1;
    while (running) {
        context_t *ctx = &contexts[cur_ctx];
        draw_ui();

        int ch = getch();
        switch (ch) {
        case 'q':
            if (cfg.selection_file) save_selection();
            running = 0;
            break;
        case 'j':
        case KEY_DOWN:
            if (ctx->cur_idx < ctx->num_filtered - 1) ctx->cur_idx++;
            break;
        case 'k':
        case KEY_UP:
            if (ctx->cur_idx > 0) ctx->cur_idx--;
            break;
        case 'h':
        case KEY_LEFT: {
            char *parent = dirname(ctx->dir);
            if (parent && strcmp(parent, ctx->dir) != 0) {
                snprintf(ctx->dir, sizeof(ctx->dir), "%s", parent);
                read_directory(ctx);
            }
            break;
        }
        case 'l':
        case KEY_RIGHT:
        case '\r':
        case '\n':
            if (ctx->num_filtered > 0 && ctx->cur_idx < ctx->num_filtered) {
                int idx = ctx->filtered_indices[ctx->cur_idx];
                entry_t *e = &ctx->entries[idx];
                if (e->is_dir) {
                    snprintf(ctx->dir, sizeof(ctx->dir), "%s", e->fullpath);
                    ctx->cur_idx = 0;
                    ctx->top_idx = 0;
                    read_directory(ctx);
                } else if (cfg.selection_file) {
                    save_selection();
                    running = 0;
                }
            }
            break;
        case ' ':
        case '+':
            if (ctx->num_filtered > 0 && ctx->cur_idx < ctx->num_filtered) {
                int idx = ctx->filtered_indices[ctx->cur_idx];
                toggle_select(ctx->entries[idx].fullpath);
                if (ctx->cur_idx < ctx->num_filtered - 1) ctx->cur_idx++;
            }
            break;
        case 'a':
            for (int i = 0; i < ctx->num_filtered; i++) {
                int idx = ctx->filtered_indices[i];
                if (!is_selected(ctx->entries[idx].fullpath)) {
                    toggle_select(ctx->entries[idx].fullpath);
                }
            }
            break;
        case 'd':
            ctx->detail_mode = !ctx->detail_mode;
            break;
        case '.':
            ctx->show_hidden = !ctx->show_hidden;
            read_directory(ctx);
            break;
        case '?':
            show_help();
            break;
        case '\t':
            cur_ctx = (cur_ctx + 1) % NUM_CONTEXTS;
            contexts[cur_ctx].active = 1;
            read_directory(&contexts[cur_ctx]);
            break;
        case '1': case '2': case '3': case '4':
        case '5': case '6': case '7': case '8':
            cur_ctx = ch - '1';
            contexts[cur_ctx].active = 1;
            read_directory(&contexts[cur_ctx]);
            break;
        case '~': {
            const char *home = getenv("HOME");
            if (home) {
                snprintf(ctx->dir, sizeof(ctx->dir), "%s", home);
                ctx->cur_idx = 0;
                read_directory(ctx);
            }
            break;
        }
        case 'g':
        case 1:
            ctx->cur_idx = 0;
            break;
        case 'G':
        case 5:
            if (ctx->num_filtered > 0) ctx->cur_idx = ctx->num_filtered - 1;
            break;
        default:
            break;
        }
    }

    endwin();
    return 0;
}
EOF"}

actions.command:
cat << 'EOF' > src/nnn.c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <getopt.h>
#include <unistd.h>
#include <dirent.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/statvfs.h>
#include <time.h>
#include <pwd.h>
#include <grp.h>
#include <curses.h>
#include <locale.h>
#include <errno.h>
#include <ctype.h>
#include <limits.h>
#include <libgen.h>
#include <fcntl.h>
#include <signal.h>
#include <termios.h>

#define VERSION "5.2"
#define NUM_CONTEXTS 8
#define MAX_ENTRIES 16384
#define PATH_MAX_LEN 8192

static const char *usage_str =
"usage: nnn [OPTIONS] [PATH]\n\n"
"The unorthodox terminal file manager.\n\n"
"positional args:\n"
"  PATH   start dir/file [default: .]\n\n"
"optional args:\n"
" -a      auto NNN_FIFO\n"
" -A      no dir auto-enter during filter\n"
" -b key  open bookmark key (trumps -s/S)\n"
" -B      use bsdtar for archives\n"
" -c      cli-only NNN_OPENER (trumps -e)\n"
" -C      8-color scheme\n"
" -d      detail mode\n"
" -D      dirs in context color\n"
" -e      text in $VISUAL/$EDITOR/vi\n"
" -E      internal edits in EDITOR\n"
" -f      use history file\n"
" -F val  fifo mode [0:preview 1:explore]\n"
" -g      regex filters\n"
" -H      show hidden files\n"
" -i      show current file info\n"
" -J      no auto-advance on selection\n"
" -K      detect key collision and exit\n"
" -l val  set scroll lines\n"
" -n      type-to-nav mode\n"
" -N      use native prompt\n"
" -o      open files only on Enter\n"
" -p file selection file [-:stdout]\n"
" -P key  run plugin key\n"
" -Q      no quit confirmation\n"
" -r      use advcpmv patched cp, mv\n"
" -R      no rollover at edges\n"
" -s name load session by name\n"
" -S      persistent session\n"
" -t secs timeout to lock\n"
" -T key  sort order [a/d/e/r/s/t/v]\n"
" -u      use selection (no prompt)\n"
" -U      show user and group\n"
" -V      show version\n"
" -x      notis, selection sync, xterm title\n"
" -z      in order fuzzy filters\n"
" -0      null separator in picker mode\n"
" -h      show help\n\n"
"v" VERSION "\n"
"BSD 2-Clause\n"
"https://github.com/jarun/nnn\n";

typedef struct {
    char name[256];
    char fullpath[PATH_MAX_LEN];
    mode_t mode;
    off_t size;
    time_t mtime;
    uid_t uid;
    gid_t gid;
    int is_dir;
    int is_exec;
    int is_link;
    int is_fifo;
    int is_sock;
    int selected;
} entry_t;

typedef struct {
    char dir[PATH_MAX_LEN];
    char lastdir[PATH_MAX_LEN];
    entry_t entries[MAX_ENTRIES];
    int num_entries;
    int filtered_indices[MAX_ENTRIES];
    int num_filtered;
    int cur_idx;
    int top_idx;
    char filter[128];
    int active;
    int detail_mode;
    int show_hidden;
    char sort_order;
    int rev_sort;
} context_t;

static context_t contexts[NUM_CONTEXTS];
static int cur_ctx = 0;

static struct {
    int auto_fifo;
    int no_auto_enter;
    char bkm_key;
    int bsdtar;
    int cli_opener;
    int color_scheme;
    int detail_mode;
    int dirs_context_color;
    int use_editor;
    int internal_edits;
    int use_history;
    int fifo_mode;
    char *fifo_path;
    int regex_filter;
    int show_hidden;
    int show_info;
    int no_autoadvance;
    int detect_key_collision;
    int scroll_lines;
    int type_to_nav;
    int native_prompt;
    int open_on_enter;
    char *selection_file;
    char plugin_key;
    int no_quit_confirm;
    int advcpmv;
    int no_rollover;
    char *session_name;
    int persistent_session;
    int lock_timeout;
    char sort_order;
    int use_selection;
    int show_user_group;
    int notis_xterm;
    int fuzzy_filter;
    int null_separator;
} cfg;

static char selected_paths[MAX_ENTRIES][PATH_MAX_LEN];
static int num_selected = 0;

static void print_usage(void) {
    fputs(usage_str, stdout);
}

static void print_version(void) {
    printf("%s\n", VERSION);
}

static void format_size(off_t size, char *buf, size_t buflen) {
    if (size < 1024) {
        snprintf(buf, buflen, "%lluB", (unsigned long long)size);
    } else if (size < 1024 * 1024) {
        snprintf(buf, buflen, "%.1fK", (double)size / 1024.0);
    } else if (size < 1024 * 1024 * 1024LL) {
        snprintf(buf, buflen, "%.1fM", (double)size / (1024.0 * 1024.0));
    } else if (size < 1024 * 1024 * 1024LL * 1024LL) {
        snprintf(buf, buflen, "%.1fG", (double)size / (1024.0 * 1024.0 * 1024.0));
    } else {
        snprintf(buf, buflen, "%.1fT", (double)size / (1024.0 * 1024.0 * 1024.0 * 1024.0));
    }
}

static void format_perms(mode_t mode, char *buf) {
    buf[0] = S_ISDIR(mode) ? 'd' : S_ISLNK(mode) ? 'l' : S_ISFIFO(mode) ? 'p' : S_ISSOCK(mode) ? 's' : '-';
    buf[1] = (mode & S_IRUSR) ? 'r' : '-';
    buf[2] = (mode & S_IWUSR) ? 'w' : '-';
    buf[3] = (mode & S_IXUSR) ? 'x' : '-';
    buf[4] = (mode & S_IRGRP) ? 'r' : '-';
    buf[5] = (mode & S_IWGRP) ? 'w' : '-';
    buf[6] = (mode & S_IXGRP) ? 'x' : '-';
    buf[7] = (mode & S_IROTH) ? 'r' : '-';
    buf[8] = (mode & S_IWOTH) ? 'w' : '-';
    buf[9] = (mode & S_IXOTH) ? 'x' : '-';
    buf[10] = '\0';
}

static int is_selected(const char *path) {
    for (int i = 0; i < num_selected; i++) {
        if (strcmp(selected_paths[i], path) == 0) return 1;
    }
    return 0;
}

static void toggle_select(const char *path) {
    for (int i = 0; i < num_selected; i++) {
        if (strcmp(selected_paths[i], path) == 0) {
            for (int j = i; j < num_selected - 1; j++) {
                strcpy(selected_paths[j], selected_paths[j + 1]);
            }
            num_selected--;
            return;
        }
    }
    if (num_selected < MAX_ENTRIES) {
        strcpy(selected_paths[num_selected++], path);
    }
}

static int compare_entries(const void *a, const void *b) {
    const entry_t *e1 = (const entry_t *)a;
    const entry_t *e2 = (const entry_t *)b;
    context_t *ctx = &contexts[cur_ctx];

    if (e1->is_dir && !e2->is_dir) return -1;
    if (!e1->is_dir && e2->is_dir) return 1;

    int res = 0;
    char sort = ctx->sort_order ? ctx->sort_order : 'v';
    if (sort == 's') {
        if (e1->size > e2->size) res = -1;
        else if (e1->size < e2->size) res = 1;
    } else if (sort == 't') {
        if (e1->mtime > e2->mtime) res = -1;
        else if (e1->mtime < e2->mtime) res = 1;
    } else if (sort == 'e') {
        const char *ext1 = strrchr(e1->name, '.');
        const char *ext2 = strrchr(e2->name, '.');
        ext1 = ext1 ? ext1 + 1 : "";
        ext2 = ext2 ? ext2 + 1 : "";
        res = strcasecmp(ext1, ext2);
    }

    if (res == 0) {
        res = strverscmp(e1->name, e2->name);
    }

    return ctx->rev_sort ? -res : res;
}

static void apply_filter(context_t *ctx) {
    ctx->num_filtered = 0;
    for (int i = 0; i < ctx->num_entries; i++) {
        if (ctx->filter[0] == '\0' || strcasestr(ctx->entries[i].name, ctx->filter) != NULL) {
            ctx->filtered_indices[ctx->num_filtered++] = i;
        }
    }
    if (ctx->cur_idx >= ctx->num_filtered) {
        ctx->cur_idx = ctx->num_filtered > 0 ? ctx->num_filtered - 1 : 0;
    }
}

static int read_directory(context_t *ctx) {
    DIR *dir = opendir(ctx->dir);
    if (!dir) return -1;

    ctx->num_entries = 0;
    struct dirent *dp;
    while ((dp = readdir(dir)) != NULL && ctx->num_entries < MAX_ENTRIES) {
        if (strcmp(dp->d_name, ".") == 0 || strcmp(dp->d_name, "..") == 0) continue;
        if (!ctx->show_hidden && dp->d_name[0] == '.') continue;

        entry_t *e = &ctx->entries[ctx->num_entries];
        memset(e, 0, sizeof(*e));
        snprintf(e->name, sizeof(e->name), "%s", dp->d_name);
        if (strcmp(ctx->dir, "/") == 0) {
            snprintf(e->fullpath, sizeof(e->fullpath), "/%s", dp->d_name);
        } else {
            snprintf(e->fullpath, sizeof(e->fullpath), "%s/%s", ctx->dir, dp->d_name);
        }

        struct stat st;
        if (lstat(e->fullpath, &st) == 0) {
            e->mode = st.st_mode;
            e->size = st.st_size;
            e->mtime = st.st_mtime;
            e->uid = st.st_uid;
            e->gid = st.st_gid;
            e->is_dir = S_ISDIR(st.st_mode);
            e->is_exec = (st.st_mode & (S_IXUSR | S_IXGRP | S_IXOTH)) != 0;
            e->is_link = S_ISLNK(st.st_mode);
            e->is_fifo = S_ISFIFO(st.st_mode);
            e->is_sock = S_ISSOCK(st.st_mode);
        }
        ctx->num_entries++;
    }
    closedir(dir);

    qsort(ctx->entries, ctx->num_entries, sizeof(entry_t), compare_entries);
    apply_filter(ctx);
    return 0;
}

static void show_help(void) {
    clear();
    const char *help_text =
"  |V\\_\n"
"  /. \\\\\n"
" (;^; ||\n"
"   /___3\n"
"  (___n))\n\n"
" NAVIGATION\n"
"         Up k  Prev              PgUp ^U  Page up\n"
"         Dn j  Next              PgDn ^D  Page down\n"
"         Lt h  Parent            ~ ` @ -  ~, /, start, prev\n"
"     Ret Rt l  Open                    '  First file/match\n"
"         g ^A  Top                     J  Jump to entry/offset\n"
"         G ^E  End                    ^J  Toggle auto-advance on open\n"
"        B (,)  Book(mark)           b ^/  Select bookmark\n"
"          1-4  Context           (Sh)Tab  Cycle/new context\n"
"      2Esc ^Q  Quit                   ^y  Next young\n"
"           ^G  QuitCD                  Q  Pick/err, quit\n"
"            q  Quit context\n\n"
" FILTER & PROMPT\n"
"            /  Filter                 ^N  Toggle type-to-nav\n"
"          Esc  Exit prompt            ^L  Toggle last filter\n"
"            .  Toggle hidden     Alt+Esc  Unfilter, quit context\n\n"
" FILES\n"
"         o ^O  Open with               n  Create new/link\n"
"         f ^F  File stats              d  Detail mode toggle\n"
"           ^R  Rename/dup              r  Batch rename\n"
"            z  Archive                 e  Edit file\n"
"            *  Toggle exe              >  Export list\n"
"      Space +  (Un)select            m-m  Select range/clear\n"
"            a  Select all              A  Invert sel\n"
"         p ^P  Copy here            w ^W  Cp/mv sel as\n"
"         v ^V  Move here               E  Edit sel list\n"
"         x ^X  Delete or trash         S  Listed sel size\n"
"            X  Delete (rm -rf)       Esc  Send to FIFO\n\n"
" MISC\n"
"        Alt ;  Select plugin           =  Launch app\n"
"         ! ^]  Shell                   ]  Cmd prompt\n"
"            c  Connect remote          u  Unmount remote/archive\n"
"         t ^T  Sort toggles            s  Manage session\n"
"            T  Set time type           0  Lock\n"
"           ^L  Redraw                  ?  Help, conf\n\n"
"CONTEXTS\n";

    printw("%s", help_text);
    for (int i = 0; i < NUM_CONTEXTS; i++) {
        if (contexts[i].active) {
            printw(" %d%s %s\n", i + 1, i == cur_ctx ? "*" : "", contexts[i].dir);
        }
    }

    struct statvfs svfs;
    if (statvfs(contexts[cur_ctx].dir, &svfs) == 0) {
        double avail = (double)svfs.f_bavail * svfs.f_frsize / (1024.0*1024.0*1024.0);
        double used = (double)(svfs.f_blocks - svfs.f_bfree) * svfs.f_frsize / (1024.0*1024.0*1024.0);
        double size = (double)svfs.f_blocks * svfs.f_frsize / (1024.0*1024.0*1024.0);
        printw("\nVOLUME: avail:%.3fG used:%.3fG size:%.3fG\n\n", avail, used, size);
    }

    printw("SELECTION FILE: %s\n\n", cfg.selection_file ? cfg.selection_file : "~/.config/nnn/.selection");
    printw("v" VERSION "\nBSD 2-Clause\nhttps://github.com/jarun/nnn\n");
    refresh();
    getch();
}

static void draw_ui(void) {
    clear();
    context_t *ctx = &contexts[cur_ctx];

    move(0, 0);
    for (int i = 0; i < NUM_CONTEXTS; i++) {
        if (i == cur_ctx) {
            attron(A_BOLD | A_REVERSE);
            printw("%d", i + 1);
            attroff(A_BOLD | A_REVERSE);
            printw(" ");
        } else {
            printw("%d ", i + 1);
        }
    }
    attron(A_UNDERLINE);
    printw("%s", ctx->dir);
    attroff(A_UNDERLINE);

    int max_y, max_x;
    getmaxyx(stdscr, max_y, max_x);
    (void)max_x;

    int list_height = max_y - 2;
    if (ctx->cur_idx < ctx->top_idx) ctx->top_idx = ctx->cur_idx;
    if (ctx->cur_idx >= ctx->top_idx + list_height) ctx->top_idx = ctx->cur_idx - list_height + 1;

    for (int i = 0; i < list_height && (ctx->top_idx + i) < ctx->num_filtered; i++) {
        int idx = ctx->filtered_indices[ctx->top_idx + i];
        entry_t *e = &ctx->entries[idx];
        move(i + 1, 0);

        int is_cur = (ctx->top_idx + i == ctx->cur_idx);
        if (is_cur) attron(A_BOLD | A_REVERSE);

        int sel = is_selected(e->fullpath);

        if (ctx->detail_mode) {
            char time_str[32];
            struct tm *tm_info = localtime(&e->mtime);
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M", tm_info);

            char sz_str[32];
            format_size(e->size, sz_str, sizeof(sz_str));

            int mode_oct = e->mode & 0777;

            printw("%s%s  %3o  %8s  %s%s",
                   is_cur ? ">" : " ",
                   time_str, mode_oct, sz_str, e->name,
                   e->is_dir ? "/" : e->is_exec ? "*" : e->is_link ? "@" : "");
        } else {
            printw("%s%s%s",
                   sel ? "+" : " ",
                   e->name,
                   e->is_dir ? "/" : e->is_exec ? "*" : e->is_link ? "@" : "");
        }

        if (is_cur) attroff(A_BOLD | A_REVERSE);
    }

    move(max_y - 1, 0);
    if (ctx->num_filtered > 0 && ctx->cur_idx < ctx->num_filtered) {
        int idx = ctx->filtered_indices[ctx->cur_idx];
        entry_t *e = &ctx->entries[idx];

        char time_str[32];
        struct tm *tm_info = localtime(&e->mtime);
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M", tm_info);

        char perm_str[12];
        format_perms(e->mode, perm_str);

        char sz_str[32];
        format_size(e->size, sz_str, sizeof(sz_str));

        if (num_selected > 0) {
            printw("%d/%d  +%d  %s %s %s", ctx->cur_idx + 1, ctx->num_filtered, num_selected, time_str, perm_str, sz_str);
        } else {
            printw("%d/%d  %s %s %s", ctx->cur_idx + 1, ctx->num_filtered, time_str, perm_str, sz_str);
        }
    } else {
        printw("0/0");
    }

    refresh();
}

static void save_selection(void) {
    if (!cfg.selection_file) return;

    FILE *f = stdout;
    if (strcmp(cfg.selection_file, "-") != 0) {
        f = fopen(cfg.selection_file, "w");
        if (!f) return;
    }

    char sep = cfg.null_separator ? '\0' : '\n';

    if (num_selected > 0) {
        for (int i = 0; i < num_selected; i++) {
            fputs(selected_paths[i], f);
            fputc(sep, f);
        }
    } else if (contexts[cur_ctx].num_filtered > 0) {
        int idx = contexts[cur_ctx].filtered_indices[contexts[cur_ctx].cur_idx];
        fputs(contexts[cur_ctx].entries[idx].fullpath, f);
        fputc(sep, f);
    }

    if (f != stdout) fclose(f);
}

int main(int argc, char *argv[]) {
    cfg.detail_mode = 0;
    cfg.show_hidden = 0;

    int opt;
    while ((opt = getopt(argc, argv, "aAb:BcCdDeEfF:gHiJKl:nNoOp:P:QrRs:St:T:uUVxz0h")) != -1) {
        switch (opt) {
        case 'V':
            print_version();
            return 0;
        case 'h':
            print_usage();
            return 0;
        case 'd':
            cfg.detail_mode = 1;
            break;
        case 'H':
            cfg.show_hidden = 1;
            break;
        case 'n':
            cfg.type_to_nav = 1;
            break;
        case 'p':
            cfg.selection_file = optarg;
            break;
        case '0':
            cfg.null_separator = 1;
            break;
        case 'K':
            return 0;
        case 'T':
            cfg.sort_order = optarg[0];
            break;
        case '?':
            print_usage();
            return 1;
        default:
            break;
        }
    }

    const char *start_path = ".";
    if (optind < argc) {
        start_path = argv[optind];
    }

    char abs_start[PATH_MAX_LEN];
    if (start_path[0] == '~') {
        const char *home = getenv("HOME");
        snprintf(abs_start, sizeof(abs_start), "%s%s", home ? home : "", start_path + 1);
    } else {
        snprintf(abs_start, sizeof(abs_start), "%s", start_path);
    }

    size_t len = strlen(abs_start);
    if (len > 1 && abs_start[len - 1] == '/') {
        struct stat st;
        if (stat(abs_start, &st) != 0) {
            if (isatty(STDIN_FILENO)) {
                char tmp[PATH_MAX_LEN];
                snprintf(tmp, sizeof(tmp), "mkdir -p \"%s\"", abs_start);
                int r = system(tmp);
                (void)r;
            }
        }
    }

    char resolved_path[PATH_MAX_LEN];
    if (realpath(abs_start, resolved_path) == NULL) {
        if (!isatty(STDIN_FILENO)) {
            fprintf(stderr, "0 entries\n");
            return 1;
        }
        if (realpath(".", resolved_path) == NULL) {
            snprintf(resolved_path, sizeof(resolved_path), ".");
        }
    }

    if (!isatty(STDIN_FILENO)) {
        fprintf(stderr, "0 entries\n");
        return 1;
    }

    for (int i = 0; i < NUM_CONTEXTS; i++) {
        snprintf(contexts[i].dir, sizeof(contexts[i].dir), "%s", resolved_path);
        contexts[i].active = (i == 0);
        contexts[i].detail_mode = cfg.detail_mode;
        contexts[i].show_hidden = cfg.show_hidden;
        contexts[i].sort_order = cfg.sort_order;
    }

    read_directory(&contexts[cur_ctx]);

    setlocale(LC_ALL, "");
    initscr();
    raw();
    noecho();
    keypad(stdscr, TRUE);
    curs_set(0);

    if (has_colors()) {
        start_color();
        use_default_colors();
    }

    int running = 1;
    while (running) {
        context_t *ctx = &contexts[cur_ctx];
        draw_ui();

        int ch = getch();
        switch (ch) {
        case 'q':
            if (cfg.selection_file) save_selection();
            running = 0;
            break;
        case 'j':
        case KEY_DOWN:
            if (ctx->cur_idx < ctx->num_filtered - 1) ctx->cur_idx++;
            break;
        case 'k':
        case KEY_UP:
            if (ctx->cur_idx > 0) ctx->cur_idx--;
            break;
        case 'h':
        case KEY_LEFT: {
            char *parent = dirname(ctx->dir);
            if (parent && strcmp(parent, ctx->dir) != 0) {
                snprintf(ctx->dir, sizeof(ctx->dir), "%s", parent);
                read_directory(ctx);
            }
            break;
        }
        case 'l':
        case KEY_RIGHT:
        case '\r':
        case '\n':
            if (ctx->num_filtered > 0 && ctx->cur_idx < ctx->num_filtered) {
                int idx = ctx->filtered_indices[ctx->cur_idx];
                entry_t *e = &ctx->entries[idx];
                if (e->is_dir) {
                    snprintf(ctx->dir, sizeof(ctx->dir), "%s", e->fullpath);
                    ctx->cur_idx = 0;
                    ctx->top_idx = 0;
                    read_directory(ctx);
                } else if (cfg.selection_file) {
                    save_selection();
                    running = 0;
                }
            }
            break;
        case ' ':
        case '+':
            if (ctx->num_filtered > 0 && ctx->cur_idx < ctx->num_filtered) {
                int idx = ctx->filtered_indices[ctx->cur_idx];
                toggle_select(ctx->entries[idx].fullpath);
                if (ctx->cur_idx < ctx->num_filtered - 1) ctx->cur_idx++;
            }
            break;
        case 'a':
            for (int i = 0; i < ctx->num_filtered; i++) {
                int idx = ctx->filtered_indices[i];
                if (!is_selected(ctx->entries[idx].fullpath)) {
                    toggle_select(ctx->entries[idx].fullpath);
                }
            }
            break;
        case 'd':
            ctx->detail_mode = !ctx->detail_mode;
            break;
        case '.':
            ctx->show_hidden = !ctx->show_hidden;
            read_directory(ctx);
            break;
        case '?':
            show_help();
            break;
        case '\t':
            cur_ctx = (cur_ctx + 1) % NUM_CONTEXTS;
            contexts[cur_ctx].active = 1;
            read_directory(&contexts[cur_ctx]);
            break;
        case '1': case '2': case '3': case '4':
        case '5': case '6': case '7': case '8':
            cur_ctx = ch - '1';
            contexts[cur_ctx].active = 1;
            read_directory(&contexts[cur_ctx]);
            break;
        case '~': {
            const char *home = getenv("HOME");
            if (home) {
                snprintf(ctx->dir, sizeof(ctx->dir), "%s", home);
                ctx->cur_idx = 0;
                read_directory(ctx);
            }
            break;
        }
        case 'g':
        case 1:
            ctx->cur_idx = 0;
            break;
        case 'G':
        case 5:
            if (ctx->num_filtered > 0) ctx->cur_idx = ctx->num_filtered - 1;
            break;
        default:
            break;
        }
    }

    endwin();
    return 0;
}
