    int is_exec;
    int is_link;
    int is_fifo;
    int is_sock;
    int selected;
} entry_t;

typedef struct {
    char dir[PATH_MAX_LEN];
    char lastdir[PATH_MAX_LEN];
    entry_t entries[MAX_ENTRIES];
    int num_entries;
    int filtered_indices[MAX_ENTRIES];
    int num_filtered;
    int cur_idx;
    int top_idx;
    char filter[128];
    int active;
    int detail_mode;
    int show_hidden;
    char sort_order;
    int rev_sort;
} context_t;

static context_t contexts[NUM_CONTEXTS];
static int cur_ctx = 0;

static struct {
    int auto_fifo;
    int no_auto_enter;
    char bkm_key;
    int bsdtar;
    int cli_opener;
    int color_scheme;
    int detail_mode;
    int dirs_context_color;
    int use_editor;
    int internal_edits;
    int use_history;
    int fifo_mode;
    char *fifo_path;
    int regex_filter;
